## Why This Is Asked

This question tests expertise with closures, per-id memoization, and real-time rendering patterns in frontend systems. It specifically targets race-condition handling and efficient UI updates under high-frequency data scenarios.

## Key Concepts

- Closure-scoped per-id caches for memory efficiency
- Per-id memoization with bounded history management
- Promise chaining to serialize renders and handle race conditions
- Debounce using requestAnimationFrame for smooth UI updates

## Code Example

```javascript
function createDataUpdater() {
  const cache = new Map(); // id -> [last 5 results]
  let renderPromise = Promise.resolve();
  let renderScheduled = false;

  const updateCache = (id, data) => {
    const history = cache.get(id) || [];
    history.push(data);
    if (history.length > 5) history.shift();
    cache.set(id, history);
  };

  const render = () => {
    renderScheduled = false;
    // Apply cache data to UI
  };

  const scheduleRender = () => {
    if (!renderScheduled) {
      renderScheduled = true;
      requestAnimationFrame(render);
    }
  };

  return {
    processBatch: (batch) => {
      renderPromise = renderPromise.then(() => {
        batch.forEach(item => updateCache(item.id, item.data));
        scheduleRender();
      });
    }
  };
}
```

## Trade-offs

**Pros:**
- Closure ensures encapsulation and prevents external cache mutation
- Bounded cache prevents memory leaks from unbounded growth
- Promise chain guarantees render ordering consistency
- requestAnimationFrame provides optimal browser rendering timing

**Cons:**
- Added complexity compared to simple direct updates
- Memory overhead from maintaining per-id histories
- Potential render lag if batches arrive faster than processing capacity
- Cache management adds computational overhead per item

This question evaluates the ability to architect a real-time analytics UI with strict tenant isolation, efficient data handling, and React optimization techniques.

**Key Concepts**
- useSyncExternalStore for subscribing to external data streams
- Memoized selectors keyed by multiple dimensions (tenantId, metricId, timeWindow)
- Per-tenant data scoping with proper cleanup on tenant switch
- Real-time rendering with virtualization for large datasets
- Interactive zoom/pan handling with debouncing

**Code Sketches**

```javascript
// Stream wrapper
function createTenantStream(tenantId, metricId) {
  let subscribers = new Set();
  let currentData = [];
  let ws = null;

  const connect = () => {
    ws = new WebSocket(`/api/tenants/${tenantId}/metrics/${metricId}`);
    ws.onmessage = (e) => {
      currentData = [...currentData, JSON.parse(e.data)];
      subscribers.forEach(fn => fn(currentData));
    };
  };

  return {
    subscribe(fn) {
      subscribers.add(fn);
      if (!ws) connect();
      return () => subscribers.delete(fn);
    },
    getSnapshot() { return currentData; }
  };
}

// Memoized selector
function createMetricSelector(tenantId, metricId, timeWindow) {
  return useMemo(() => (data) => {
    const filtered = data.filter(d => 
      d.timestamp >= Date.now() - timeWindow
    );
    return downsample(filtered, 5000);
  }, [tenantId, metricId, timeWindow]);
}

// LineChart with virtualization
const LineChart = React.memo(function LineChart({ data, width, height }) {
  const canvasRef = useRef(null);
  return <canvas ref={canvasRef} width={width} height={height} />;
});

// Panel wiring
function PerTenantAnalyticsPanel({ tenantId, metricId, timeWindow }) {
  const theme = useContext(ThemeContext);
  const stream = useMemo(
    () => createTenantStream(tenantId, metricId),
    [tenantId, metricId]
  );
  const data = useSyncExternalStore(stream.subscribe, stream.getSnapshot);
  const selectMetric = createMetricSelector(tenantId, metricId, timeWindow);
  const series = selectMetric(data);

  useEffect(() => {
    return () => { /* cleanup zoom/pan state */ };
  }, [tenantId]);

  return <LineChart data={series} theme={theme} />;
}
```

## Why This Is Asked
This question tests the ability to design a streaming, per-tenant UI with time-based playback, memory controls, and precise cleanup when tenants switch. It exercises useSyncExternalStore, memoized selectors keyed by (tenantId, timeWindow), bounded ring buffers to cap memory, React.memo for EventRow components, playback controls (play/pause and seek), and tenant switch cleanup.

## Key Concepts
- useSyncExternalStore for external streams
- memoized selectors keyed by (tenantId, timeWindow)
- Bounded ring buffer to cap memory
- React.memo for EventRow components
- Playback controls: play/pause and seek
- Tenant switch cleanup

## Code Example
```javascript
// Stream wrapper using useSyncExternalStore
function useAuditStream(tenantId) {
  const storeRef = useRef(null);
  if (!storeRef.current) {
    storeRef.current = createAuditStore(tenantId);
  }
  return useSyncExternalStore(
    storeRef.current.subscribe,
    storeRef.current.getSnapshot,
    storeRef.current.getServerSnapshot
  );
}

// Memoized selector keyed by (tenantId, timeWindow)
const selectBoundedEvents = memoize((tenantId, timeWindow) => {
  return (events) => {
    const cutoff = Date.now() - timeWindow;
    return events
      .filter(e => e.tenantId === tenantId && e.timestamp > cutoff)
      .slice(-120); // Bounded to 120 events
  };
});

// React.memo EventRow
const EventRow = memo(({ event }) => (
  <div>{event.action} - {event.timestamp}</div>
));

// Panel wiring
function AuditPanel({ tenantId }) {
  const events = useAuditStream(tenantId);
  const boundedEvents = useMemo(
    () => selectBoundedEvents(tenantId, 120000),
    [tenantId]
  )(events);

  return (
    <div>
      {boundedEvents.map(e => <EventRow key={e.id} event={e} />)}
    </div>
  );
}
```

## Why This Is Asked
Tests mastery of closures, per-domain rate limiting, and Promise deduplication—common in real apps with multiple data sources.

## Key Concepts
- Per-domain rate limiting (token bucket)
- In-flight deduplication of identical URLs via shared Promise
- TTL-based caching with automatic refresh
- Closure-based state encapsulation for domain data
- Robust error handling and cancellation considerations

## Code Example
```javascript
class RateLimitedFetcher {
  constructor(maxPerSec = 4, ttl = 30000) {
    this.maxPerSec = maxPerSec;
    this.ttl = ttl;
    this.domainBuckets = new Map(); // domain -> { tokens, queue }
    this.cache = new Map(); // url -> { data, expiry }
    this.inFlight = new Map(); // url -> Promise
  }
  _domain(domain) {
    if (!this.domainBuckets.has(domain)) {
      this.domainBuckets.set(domain, { tokens: maxPerSec, queue: [] });
    }
    return this.domainBuckets.get(domain);
  }
  async fetch(url, init) {
    const now = Date.now();
    const cached = this.cache.get(url);
    if (cached && cached.expiry > now) return cached.data;
    if (this.inFlight.has(url)) return this.inFlight.get(url);
    const domain = new URL(url).host;
    const bucket = this._domain(domain);
    const attempt = () => {
      if (bucket.tokens > 0) {
        bucket.tokens--;
        return true;
      }
      return false;
    };
    const run = async () => {
      try {
        const res = await fetch(url, init);
        const data = await res.clone().json().catch(() => res.text());
        this.cache.set(url, { data, expiry: Date.now() + this.ttl });
        return data;
      } finally {
        bucket.tokens++;
        // drain queued requests if any
        if (bucket.queue.length) {
          const next = bucket.queue.shift();
          next();
        }
      }
    };
    const promise = (async () => {
      if (!attempt()) {
        await new Promise(r => bucket.queue.push(r));
      }
      return run();
    })();
    this.inFlight.set(url, promise);
    const result = await promise;
    this.inFlight.delete(url);
    return result;
  }
  invalidate(url) { this.cache.delete(url); }
  warmRefresh(url) { this.invalidate(url); return this.fetch(url); }
}
```

